def list_integrations() -> list[dict[str, object]]:
    return [dict(item) for item in PROVIDER_INTEGRATIONS]

def get_integration(integration_id: str) -> dict[str, object] | None:
    item = next((row for row in PROVIDER_INTEGRATIONS if row["id"] == integration_id), None)
    return dict(item) if item is not None else None

def validate_integration_registry() -> dict[str, object]:
    ids = [str(item["id"]) for item in PROVIDER_INTEGRATIONS]
    duplicates = sorted({value for value in ids if ids.count(value) > 1})
    return {
        "structurally_valid": not duplicates,
        "integration_count": len(PROVIDER_INTEGRATIONS),
        "duplicate_ids": duplicates,
        "api_documentation_verified_count": sum(bool(item["api_documentation_verified"]) for item in PROVIDER_INTEGRATIONS),
        "live_connection_verified_count": sum(bool(item["live_connection_verified"]) for item in PROVIDER_INTEGRATIONS),
        "registry_status": "catalog_reference_only",
    }
